        fprintf(stderr, "cannot open input: %s\n", strerror(errno));
        return 1;
    }

    size_t buffer_capacity = 512;
    char const *original_buffer = NULL;

    while (true) {
        char *new_buffer = realloc(original_buffer, buffer_capacity);

        if (new_buffer == NULL) {
            fprintf(stderr, "cannot expand output buffer\n");
            fclose(input);
            free(original_buffer);
            return 1;
        }

        original_buffer = new_buffer;

        size_t read_length = fread(original_buffer + len, 1,
                                   buffer_capacity - len, input);

        if (read_length == 0) {
            if (ferror(input) != 0) {
                fprintf(stderr, "cannot read input\n");
            }

            break;
        }

        len += read_length;

        if (len == buffer_capacity) {
            buffer_capacity *= 2;
        }
    }

    fclose(input);

    if (len == 0) {
        return 0;
    }

    if (setlocale(LC_CTYPE, "") == NULL) {
        fprintf(stderr, "cannot determine C locale\n");
        free(original_buffer);
        return 1;
    }

    char *destination = malloc(len);

    if (destination == NULL) {
        fprintf(stderr, "cannot allocate buffer\n");
        free(original_buffer);
        return 1;
    }

    for (size_t i = 0, j = len - 1; i < len; ++i, --j) {
        destination[i] = original_buffer[j];
    }

    if (fwrite(destination, 1, len, stdout) != len) {
        fprintf(stderr, "cannot write output\n");
        free(destination);
        free(original_buffer);
        return 1;
    }

    return 0;
}
