def count_divisible_pairs(nums, k):
    if k == 0:
        return 0
    counts = {}
    for x in nums:
        counts[x % k] = counts.get(x % k, 0) + 1
    r = counts.get(0, 0)
    total = r * (r - 1) // 2
    for i in range(1, k // 2 + 1):
        i2 = k - i
        total += counts[i] * counts[i2]
    if k % 2 == 0:
        total += counts[k // 2] * (counts[k // 2] - 1) // 2
    return total
```

