def count_divisible_pairs(nums, k):
    counts = [0] * k
    for x in nums:
        counts[x % k] += 1
    result = counts[0] * (counts[0] - 1) // 2
    for i in range(1, (k + 1) // 2):
        result += counts[i] * counts[k - i]
    if k % 2 == 0:
        result += counts[k // 2] * (counts[k // 2] - 1) // 2
    return result
```

