```python
def missing_shelf_ranges(stocked, low, high):
    stock = set(stocked)
    gaps = []
    next_ = low
    while next_ < high + 1:
        if next_ not in stock:
            start = next_
            next_ += 1
            while next_ < high + 1 and next_ not in stock:
                next_ += 1
            if start != next_ - 1:
                gaps.append((start, next_ - 1))
        else:
            next_ += 1
    return gaps
```

