def eval_digits(s):
    ops = {'+': lambda a, b: a + b, '-': lambda a, b: a - b, '*': lambda a, b: a * b, '/': lambda a, b: a // b}
    stack = []
    for ch in s:
        if ch in ops:
            b, a = stack.pop(), stack.pop()
            stack.append(ops[ch](a, b))
        else:
            stack.append(int(ch))
    return stack[0]
```

```python
def eval_digits(expr):
    ops = {'+': lambda a, b: a + b, '-': lambda a, b: a - b, '*': lambda a, b: a * b}
    stack = []
    for ch in expr:
        if ch in ops:
            b = int(stack.pop())
            a = int(stack.pop())
            stack.append(ops[ch](a, b))
        else:
            stack.append(ch)
    return int(stack[0])
```

