def count_distinct_windows(readings, k):
    if k <= 0:
        return 0
    counts = {}
    total = 0
    for i, x in enumerate(readings):
        counts[x] = counts.get(x, 0) + 1
        if i >= k:
            if counts[readings[i - k]] == 1:
                total -= 1
            counts[readings[i - k]] -= 1
        if i >= k - 1:
            m = len(counts.values()) - (counts.values().count(0))
            if m == k:
                total += 1
    return total
```

```python
def count_distinct_windows(readings, k):
    if k <= 0:
        return 0
    count = 0
    seen = set()
    left = 0
    for right, x in enumerate(readings):
        seen.add(x)
        while len(seen) < k or right - left + 1 > k:
            seen.remove(readings[left])
            left += 1
        if right - left + 1 == k:
            count += 1
    return count
```

