def is_prime(num):
    """Check if a number is a prime number."""
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num ** 0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def has_prime_parity_duplicates(nums, k):
    """Check if there are any two distinct indices i and j in the array such that nums[i] == nums[j], |i - j| <= k,
    and both nums[i] and nums[j] are prime numbers with the same parity."""
    seen = {}
    for index, value in enumerate(nums):
        if not is_prime(value):
            continue
        if seen.get((value, index % 2), None) is not None:
            return True
        seen[(value, index % 2)] = index
        if index - k > 0:
            del seen[(nums[index - k - 1], (index - k - 1) % 2)]
    return False
```

