def is_prime(n):
    """Check if a number is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def contains_duplicates_within_k_distance(nums, k):
    """Determine if there are any two distinct indices i and j in the array such that nums[i] == nums[j], |i - j| <= k, and both nums[i] and nums[j] are prime numbers with the same parity."""
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, min(i + k + 1, n)):
            if nums[i] == nums[j] and (is_prime(nums[i]) and (nums[i] % 2 == nums[j] % 2)):
                return True
    return False
