def remove_runs(s, k):
    if k <= 0 or not s:
        return s
    stack = []
    for ch in s:
        if stack and stack[-1][0] == ch:
            stack[-1][1] += 1
            if stack[-1][1] == k:
                stack.pop()
        else:
            stack.append([ch, 1])
    result = []
    for ch, cnt in stack:
        result.append(ch * cnt)
    return ''.join(result)
```

