def earliest_meeting(a, b, duration):
    i = j = 0
    while i < len(a) and j < len(b):
        x, y = [max(a[i][0], b[j][0]), min(a[i][1], b[j][1])]
        if y - x >= duration:
            return (x, x + duration)
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return None
```

```python
def earliest_meeting(slots_a, slots_b, duration):
    la, r_a = 0, len(slots_a)
    lb, r_b = 0, len(slots_b)
    while la < r_a and lb < r_b:
        a = slots_a[la][0]
        b = slots_b[lb][0]
        if a > b:
            lb += 1
            continue
        if a + duration > min(slots_a[la][1], slots_b[lb][1]):
            return (max(a, b), max(a, b) + duration)
        if a + duration < min(slots_a[la][1], slots_b[lb][1]):
            return (a, a + duration)
        if b + duration < min(slots_a[la][1], slots_b[lb][1]):
            return (b, b + duration)
        la += 1
        lb += 1
    return None
```

