def classify_number(n):
    if n < 2:
        return 'deficient'
    sigma = 1
    p = 2
    while p * p <= n:
        if n % p == 0:
            p2 = p
            while p2 * p2 != n:
                sigma += p + p2
                p2 += p
            sigma += n // p
        p += 1
    sigma -= n
    if sigma == n:
        return 'perfect'
    if sigma > n:
        return 'abundant'
    return 'deficient'
```

