def shortest_span_all_levels(entries):
    from itertools import islice, permutations
    if not set(level[1] for level in entries):
        return None
    for p in permutations(sorted(set(level[1] for level in entries))):
        ls = [level[0] for level in entries if level[1] in p]
        try:
            vals = {p[0]: ls[ls.index(p[0])]}
            d = {p[1]: ls[ls.index(p[1])]}
            for c in p[2:]:
                v = ls[ls.index(c)]
                vals[c] = v
                d[c] = v
                if vals[p[0]] > vals[c]:
                    vals[p[0]] = vals[c]
                if d[p[1]] > d[c]:
                    d[p[1]] = d[c]
        except ValueError:
            continue
        span = max(vals.values()) - min(d.values())
        if span is not None and (result is None or span < result):
            result = span
    return result
```

